mapper.update:
UPDATE loa_types
SET label = #{label}, accrual_treatment = #{accrualTreatment},
    evidence_required = #{evidenceRequired}, active = #{active}, sort_order = #{sortOrder}
WHERE code = #{code}

UPDATE loa_requests
SET status = #{status}, decided_by = #{decidedBy}, rejected_reason = #{rejectedReason}
WHERE id = #{id}

UPDATE loa_requests
SET status = CASE WHEN start_date > #{lastLeaveDate} THEN 'CANCELED' ELSE status END,
    end_date = CASE WHEN start_date > #{lastLeaveDate} THEN end_date
                    WHEN end_date IS NULL OR end_date > #{lastLeaveDate} THEN #{lastLeaveDate}
                    ELSE end_date END,
    decided_by = #{decidedBy}
WHERE user_id = #{userId} AND type = #{type} AND start_date = #{startDate}
  AND status = 'APPROVED'
